package cn.sifangguan.hotelaios.finance;

import cn.sifangguan.hotelaios.shared.audit.AuditWriter;
import cn.sifangguan.hotelaios.shared.context.TenantPrincipal;
import cn.sifangguan.hotelaios.shared.db.TenantDatabaseContext;
import cn.sifangguan.hotelaios.shared.security.*;
import org.springframework.jdbc.core.namedparam.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.time.*;
import java.util.*;
import static cn.sifangguan.hotelaios.finance.FinanceV2Support.*;

/** Human recommendation closure only: no task.create, payments, postings, tax decisions or KPI writes. */
@Service @Transactional
public class FinanceInsightActionService {
 private final NamedParameterJdbcTemplate jdbc;private final TenantDatabaseContext database;private final AccessPolicy access;private final AuditWriter audit;
 private final FinanceInsightService insights;private final FinanceArchiveSources sources;private final EffectiveIdentityService identities;
 public FinanceInsightActionService(NamedParameterJdbcTemplate jdbc,TenantDatabaseContext database,AccessPolicy access,AuditWriter audit,FinanceInsightService insights,FinanceArchiveSources sources,EffectiveIdentityService identities){this.jdbc=jdbc;this.database=database;this.access=access;this.audit=audit;this.insights=insights;this.sources=sources;this.identities=identities;}
 private TenantPrincipal prepare(){access.requireAnyPermission("finance.submit","finance.review","finance.configure","finance.read","finance.accounting.read");var p=access.principal();database.apply(p.tenantId());return p;}
 private static boolean has(TenantPrincipal p,String permission){return p.hasPermission("*")||p.hasPermission(permission);}
 private static boolean canAct(TenantPrincipal p){return has(p,"finance.submit")||has(p,"finance.review")||has(p,"finance.configure");}
 private void lockProof(String type,UUID source){String table=switch(type){case "CLAIM"->"finance_claim";case "OPERATION"->"fo_document";case "VOUCHER"->"fa_voucher";case "REVENUE"->"fb_revenue_batch";case "PAYROLL"->"fb_payroll_batch";case "TAX_RETURN"->"fb_tax_return";case "INTERCOMPANY"->"fb_intercompany";default->throw bad("不支持此核实依据");};if(jdbc.queryForList("select id from "+table+" where tenant_id=:tenant and id=:id for share",base(access.principal()).addValue("id",source)).isEmpty())throw missing();}
 public Map<String,Object> assignees(UUID hotel){var p=prepare();access.requirePermission("finance.review");access.requireOrgScope(hotel);var visible=new ArrayList<Map<String,Object>>();var candidates=jdbc.queryForList("select id,display_name from user_account where tenant_id=:tenant and status='ACTIVE' order by display_name,id limit 1000",base(p));for(var account:candidates){UUID user=id(account.get("id"));boolean own=eligible(p,user,hotel,false),review=eligible(p,user,hotel,true);if(own||review)visible.add(Map.of("id",user,"name",account.get("display_name"),"canOwn",own,"canReview",review));}return output(Map.of("items",visible,"candidateWindow",1000,"hasMoreCandidates",candidates.size()==1000,"note","仅列实时身份有该门店范围及对应办理/审核权限的实际账号，不按岗位名推断，不自动授权"));}
 public Map<String,Object> candidates(UUID taskId,String type,int page){var p=prepare();var task=task(p,taskId,false);if(!p.actorId().equals(task.get("owner_id"))&&!p.actorId().equals(task.get("reviewer_id")))throw new AccessDeniedException("仅实际责任人或指定核实人可以检索办理依据");if(page<0||page>10000)throw bad("来源页码无效");String query=switch(type){case "CLAIM"->"select id from finance_claim where tenant_id=:tenant and hotel_id=:hotel and company_id=:company and status in ('APPROVED','PAID')";case "OPERATION"->"select id from fo_document where tenant_id=:tenant and hotel_id=:hotel and company_id=:company and status='APPROVED'";case "VOUCHER"->"select v.id from fa_voucher v join fa_book b on b.tenant_id=v.tenant_id and b.id=v.book_id where v.tenant_id=:tenant and b.hotel_id=:hotel and b.company_id=:company and v.status='POSTED' and v.reversed_by_id is null";case "REVENUE"->"select id from fb_revenue_batch where tenant_id=:tenant and hotel_id=:hotel and company_id=:company and status='CONFIRMED'";case "PAYROLL"->"select id from fb_payroll_batch where tenant_id=:tenant and hotel_id=:hotel and company_id=:company and status='CONFIRMED'";case "TAX_RETURN"->"select t.id from fb_tax_return t where t.tenant_id=:tenant and t.hotel_id=:hotel and t.company_id=:company and exists(select 1 from fb_tax_receipt r where r.tenant_id=t.tenant_id and r.return_id=t.id and r.kind='FILING')";default->throw bad("不支持此依据类型");};if(type.equals("PAYROLL"))access.requirePermission("finance.payroll");if(type.equals("TAX_RETURN"))access.requirePermission("finance.tax");var found=jdbc.queryForList(query+" order by 1 limit 100 offset :offset",base(p).addValue("hotel",task.get("hotel_id")).addValue("company",task.get("company_id")).addValue("offset",page*100));var visible=new ArrayList<Map<String,Object>>();for(var candidate:found){try{UUID source=id(candidate.get("id"));var resolved=proof(task,type,source);var payload=map(resolved.get("payload"));visible.add(Map.of("id",source,"sourceType",type,"title",Objects.toString(payload.getOrDefault("title",payload.getOrDefault("summary",payload.getOrDefault("sourceReference",source.toString())))),"status",Objects.toString(payload.get("status"),"REAL_RECEIPT"),"sourceVersion",resolved.get("sourceVersion")));}catch(AccessDeniedException|org.springframework.web.server.ResponseStatusException denied){/* Catalog metadata is disclosed only after actual source authorization and proof validation. */}}return output(Map.of("items",visible,"page",page,"hasMoreCandidates",found.size()==100,"candidateWindow",100,"note","按真实来源授权过滤后的候选页；页面为空不表示没有更后页资料"));}
 private Map<String,Object> task(TenantPrincipal p,UUID id,boolean lock){var found=jdbc.queryForList("select * from fi_action_task where tenant_id=:tenant and id=:id"+(lock?" for update":""),base(p).addValue("id",id));if(found.isEmpty())throw missing();var row=found.getFirst();access.requireOrgScope(id(row.get("hotel_id")));if(!p.actorId().equals(row.get("owner_id"))&&!p.actorId().equals(row.get("reviewer_id"))&&!has(p,"finance.configure"))throw new AccessDeniedException("仅指定责任人、独立核实人或有范围的配置人可读取此跟进事项");return row;}
 public Map<String,Object> list(int page){var p=prepare();if(page<0||page>10000)throw bad("页码超出允许范围");var b=base(p).addValue("page",page*50).addValue("manager",has(p,"finance.configure"));String filter=" from fi_action_task t join org_unit h on h.tenant_id=t.tenant_id and h.id=t.hotel_id where t.tenant_id=:tenant and (:tenantScope or t.hotel_id in (:scopes)) and (t.owner_id=:actor or t.reviewer_id=:actor or :manager)";return output(Map.of("items",jdbc.queryForList("select t.id,t.title,t.status,t.hotel_id,t.company_id,h.name as hotel_name,t.owner_id,t.reviewer_id,t.due_date,t.report_id,t.report_revision,t.source_report_version,t.version,t.updated_at,t.due_date<(select (clock_timestamp() at time zone timezone)::date from tenant where id=:tenant) and t.status not in ('DONE','CANCELLED') as overdue"+filter+" order by (t.status in ('DONE','CANCELLED')),t.due_date,t.id limit 50 offset :page",b),"total",jdbc.queryForObject("select count(*)"+filter,b,Long.class),"page",page,"pageSize",50));}
 public Map<String,Object> detail(UUID id){var p=prepare();var row=task(p,id,false);var out=new LinkedHashMap<>(row);var b=base(p).addValue("id",id);out.put("history",jdbc.queryForList("select id,from_status,to_status,task_version,note,actor_id,created_at from fi_action_update where tenant_id=:tenant and task_id=:id order by task_version",b));out.put("evidence",jdbc.queryForList("select id,submission_version,source_type,source_id,source_version,source_hash,submitted_by,created_at from fi_action_evidence where tenant_id=:tenant and task_id=:id order by submission_version,created_at,id",b));out.put("canWork",canAct(p)&&p.actorId().equals(row.get("owner_id"))&&Set.of("OPEN","IN_PROGRESS","REWORK").contains(row.get("status")));out.put("canReview",has(p,"finance.review")&&p.actorId().equals(row.get("reviewer_id"))&&"SUBMITTED".equals(row.get("status")));out.put("canCancel",has(p,"finance.review")&&p.actorId().equals(row.get("created_by"))&&Set.of("OPEN","IN_PROGRESS","REWORK").contains(row.get("status")));out.put("operationBoundary","仅记录采纳建议及独立核实结果，不自动执行财务、审批、税务或KPI动作；原件仍走原来源受保护下载");return output(out);}
 public Map<String,Object> assign(FinanceInsightActionModels.Assign in){var p=prepare();access.requirePermission("finance.review");access.requireOrgScope(in.hotelId());if(in.ownerId().equals(in.reviewerId()))throw bad("责任人与独立核实人不能是同一账号");var b=base(p).addValue("id",in.requestId());String hash=FinanceService.hash(json(in));jdbc.queryForObject("select pg_advisory_xact_lock(hashtextextended(:key,0))",base(p).addValue("key",p.tenantId()+":fi-action:"+in.requestId()),Object.class);var old=jdbc.queryForList("select * from fi_action_task where tenant_id=:tenant and id=:id",b);if(!old.isEmpty()){if(!hash.equals(old.getFirst().get("request_hash"))||!p.actorId().equals(old.getFirst().get("created_by")))throw conflict("分配请求编号已绑定其他建议或经办账号");return detail(in.requestId());}
  var report=insights.detail(in.reportId());if(!"PUBLISHED".equals(report.get("status"))||((Number)report.get("version")).intValue()!=in.reportRevision())throw conflict("只能分配已独立复核发布的当前报告修订");var recommendations=rows(map(report.get("content")).get("recommendations"));if(in.recommendationIndex()<0||in.recommendationIndex()>=recommendations.size())throw bad("建议序号不存在");var frozen=map(report.get("snapshot"));var books=rows(frozen.get("books")).stream().filter(r->in.hotelId().equals(id(r.get("hotelId")))).toList();if(books.size()!=1)throw bad("目标门店必须对应本次冻结报告的唯一真实账套及法人");UUID company=id(books.getFirst().get("companyId"));var adoption=jdbc.queryForList("select * from fi_recommendation where tenant_id=:tenant and report_id=:report and report_version=:revision and recommendation_index=:index and status in ('ADOPTED','IN_PROGRESS') and owner_id=:owner",base(p).addValue("report",in.reportId()).addValue("revision",in.reportRevision()).addValue("index",in.recommendationIndex()).addValue("owner",in.ownerId()));if(adoption.isEmpty())throw conflict("请先明确采纳此修订的建议并指定同一责任人，再显式分配跟进");
  requireIdentity(p,in.ownerId(),in.hotelId(),false);requireIdentity(p,in.reviewerId(),in.hotelId(),true);var suggestion=recommendations.get(in.recommendationIndex());b.addValue("report",in.reportId()).addValue("revision",in.reportRevision()).addValue("index",in.recommendationIndex()).addValue("hotel",in.hotelId()).addValue("company",company).addValue("owner",in.ownerId()).addValue("reviewer",in.reviewerId()).addValue("title",in.title()).addValue("suggestion",suggestion.get("text")).addValue("citations",json(suggestion.get("citations"))).addValue("sourceVersion",frozen.get("reportVersion")).addValue("due",in.dueDate()).addValue("hash",hash);
  jdbc.update("insert into fi_action_task(id,tenant_id,report_id,report_revision,recommendation_index,hotel_id,company_id,owner_id,reviewer_id,title,recommendation_text,citations,source_report_version,due_date,created_by,request_hash) values(:id,:tenant,:report,:revision,:index,:hotel,:company,:owner,:reviewer,:title,:suggestion,cast(:citations as jsonb),:sourceVersion,:due,:actor,:hash)",b);record(p,in.requestId(),in.requestId(),null,"OPEN",0,in.note(),hash,List.of());notify(p,in.requestId(),in.ownerId(),"ASSIGNED",0);audit.record("FINANCE_INSIGHT_ACTION_ASSIGNED","FI_ACTION",in.requestId(),json(in));return detail(in.requestId());
 }
 private boolean eligible(TenantPrincipal p,UUID account,UUID hotel,boolean reviewer){if(jdbc.queryForObject("select count(*) from user_account where tenant_id=:tenant and id=:account and status='ACTIVE'",base(p).addValue("account",account),Integer.class)!=1)return false;var assignments=jdbc.queryForList("select a.id from employee_position_assignment a join employee e on e.tenant_id=a.tenant_id and e.id=a.employee_id where a.tenant_id=:tenant and e.account_id=:account and e.employment_status='ACTIVE' and a.status='ACTIVE' and a.valid_from<=current_date and (a.valid_to is null or a.valid_to>=current_date)",base(p).addValue("account",account));var ids=new ArrayList<UUID>();ids.add(null);for(var row:assignments)ids.add(id(row.get("id")));for(UUID assignment:ids){var candidate=identities.inspectNotificationRecipient(p.tenantId(),account,assignment);if(candidate.isPresent()){var actual=candidate.get();if((actual.hasTenantScope()||actual.orgScopes().contains(hotel))&&(reviewer?has(actual,"finance.review"):canAct(actual)))return true;}}return false;}
 private void requireIdentity(TenantPrincipal p,UUID account,UUID hotel,boolean reviewer){if(!eligible(p,account,hotel,reviewer))throw conflict(reviewer?"独立核实人当前没有此门店的财务审核权限；分配不会自动授予权限":"责任人当前没有此门店的财务办理权限或有效任职；分配不会自动授予权限");}
 public Map<String,Object> start(UUID id,FinanceInsightActionModels.Move in){var p=prepare();var row=task(p,id,true);owner(p,row);String hash=requestHash("START",id,in);if(replay(p,id,in.requestId(),hash))return detail(id);version(row,in.expectedVersion());if(!"OPEN".equals(row.get("status")))throw conflict("只有新分配事项可以开始办理");change(p,row,"IN_PROGRESS",in.requestId(),in.note(),hash,List.of(),false);return detail(id);}
 public Map<String,Object> preview(UUID id,String sourceType,UUID sourceId){var p=prepare();var row=task(p,id,false);if(!p.actorId().equals(row.get("owner_id"))&&!p.actorId().equals(row.get("reviewer_id")))throw new AccessDeniedException("配置权限不能代替责任人或核实人的原来源读取");var proof=proof(row,sourceType,sourceId);return output(Map.of("sourceType",sourceType,"sourceId",sourceId,"sourceVersion",proof.get("sourceVersion"),"sourceHash",FinanceArchiveSources.canonicalHash(proof),"status",Objects.toString(map(proof.get("payload")).get("status"),"REAL_RECEIPT"),"graph",proof.get("graph"),"guidance","只接受真实已验证来源；提交与独立核实会重新授权并核对完全相同的版本和原件哈希"));}
 public Map<String,Object> submit(UUID id,FinanceInsightActionModels.Submit in){var p=prepare();var row=task(p,id,true);owner(p,row);String hash=requestHash("SUBMIT",id,in);if(replay(p,id,in.requestId(),hash))return detail(id);version(row,in.expectedVersion());if(!Set.of("OPEN","IN_PROGRESS","REWORK").contains(row.get("status")))throw conflict("当前状态不能提交核实");if(in.evidence()==null||in.evidence().isEmpty()||in.evidence().size()>20)throw bad("必须提供1至20份真实已验证业务来源、原件或复核依据");var evidenceIds=new ArrayList<UUID>();var seen=new HashSet<String>();for(var input:in.evidence()){if(!seen.add(input.sourceType()+":"+input.sourceId()))throw bad("同一来源不能重复充当多份依据");var evidence=proof(row,input.sourceType(),input.sourceId());if(!input.expectedSourceVersion().equals(evidence.get("sourceVersion")))throw conflict("核实依据版本已变化，请重新读取当前来源");UUID evidenceId=UUID.randomUUID();evidenceIds.add(evidenceId);jdbc.update("insert into fi_action_evidence(id,tenant_id,task_id,submission_version,source_type,source_id,source_version,source_hash,snapshot,submitted_by) values(:proof,:tenant,:id,:version,:type,:source,:sourceVersion,:hash,cast(:snapshot as jsonb),:actor)",base(p).addValue("proof",evidenceId).addValue("id",id).addValue("version",in.expectedVersion()+1).addValue("type",input.sourceType()).addValue("source",input.sourceId()).addValue("sourceVersion",input.expectedSourceVersion()).addValue("hash",FinanceArchiveSources.canonicalHash(evidence)).addValue("snapshot",json(evidence)));}
  change(p,row,"SUBMITTED",in.requestId(),in.note(),hash,evidenceIds,true);notify(p,id,id(row.get("reviewer_id")),"VERIFY",in.expectedVersion()+1);return detail(id);
 }
 private void owner(TenantPrincipal p,Map<String,Object> row){if(!p.actorId().equals(row.get("owner_id"))||!canAct(p))throw new AccessDeniedException("只有当前责任人在本人权限范围内可以办理；审核或配置权限不能代做他人事项");}
 private Map<String,Object> proof(Map<String,Object> task,String type,UUID source){if(!Set.of("CLAIM","OPERATION","REVENUE","PAYROLL","INTERCOMPANY","VOUCHER","TAX_RETURN").contains(type))throw bad("完成依据须为真实已验证业务/总账凭证/申报回执，不接受自报JSON、分析建议或迁移草稿");lockProof(type,source);var resolved=sources.resolve(type,source);var hotels=(Collection<?>)resolved.get("hotelIds");var companies=(Collection<?>)resolved.get("companyIds");if(hotels.size()!=1||companies.size()!=1||!hotels.stream().allMatch(h->id(h).equals(id(task.get("hotel_id"))))||!companies.stream().allMatch(c->id(c).equals(id(task.get("company_id")))))throw bad("核实依据必须与本事项的门店及冻结法人完全一致，不接收其他主体或跨门店资料");var payload=map(resolved.get("payload"));String status=Objects.toString(payload.get("status"),"");boolean verified=switch(type){case "VOUCHER"->status.equals("POSTED")&&payload.get("reversedById")==null;case "CLAIM"->Set.of("APPROVED","PAID").contains(status);case "OPERATION"->status.equals("APPROVED");case "REVENUE","PAYROLL","INTERCOMPANY"->status.equals("CONFIRMED");case "TAX_RETURN"->rows(payload.getOrDefault("receipts",List.of())).stream().anyMatch(r->"FILING".equals(r.get("kind"))&&r.get("attachmentId")!=null&&!Objects.toString(r.get("externalReference"),"").isBlank());default->false;};if(!verified)throw conflict("依据尚未完成真实业务确认、独立审批或正式过账，不能用草稿宣告问题已解决");for(var original:rows(payload.getOrDefault("attachments",List.of()))){if(!Set.of("CLEAN","BYPASSED_DEVELOPMENT").contains(Objects.toString(original.get("scanStatus"),""))||!Objects.toString(original.get("sha256"),"").matches("[a-fA-F0-9]{64}"))throw conflict("依据原件尚未通过安全检查或缺少真实哈希");}sources.authorizeLinked(resolved);return resolved;}
 public Map<String,Object> review(UUID id,FinanceInsightActionModels.Review in){var p=prepare();access.requirePermission("finance.review");var row=task(p,id,true);if(!p.actorId().equals(row.get("reviewer_id"))||p.actorId().equals(row.get("owner_id"))||p.actorId().equals(row.get("submitted_by")))throw new AccessDeniedException("只有指定的独立核实人可以审核，责任人不能自证完成");String hash=requestHash("REVIEW",id,in);if(replay(p,id,in.requestId(),hash))return detail(id);version(row,in.expectedVersion());if(!"SUBMITTED".equals(row.get("status")))throw conflict("只能审核当前已提交核实的版本");var evidence=jdbc.queryForList("select * from fi_action_evidence where tenant_id=:tenant and task_id=:id and submission_version=:submission order by id",base(p).addValue("id",id).addValue("submission",row.get("submission_version")));if(evidence.isEmpty())throw conflict("当前提交缺少不可变真实来源依据");var evidenceIds=new ArrayList<UUID>();for(var old:evidence){evidenceIds.add(id(old.get("id")));if(in.approve()){var live=proof(row,old.get("source_type").toString(),id(old.get("source_id")));if(!old.get("source_version").equals(live.get("sourceVersion"))||!old.get("source_hash").equals(FinanceArchiveSources.canonicalHash(live)))throw conflict("原来源或原件版本已变化，不能确认旧依据完成；请退回后重新提交当前依据");}}
  change(p,row,in.approve()?"DONE":"REWORK",in.requestId(),in.note(),hash,evidenceIds,false);notify(p,id,id(row.get("owner_id")),in.approve()?"DONE":"REWORK",in.expectedVersion()+1);return detail(id);
 }
 public Map<String,Object> cancel(UUID id,FinanceInsightActionModels.Move in){var p=prepare();access.requirePermission("finance.review");var row=task(p,id,true);if(!p.actorId().equals(row.get("created_by")))throw new AccessDeniedException("仅原分配人可以说明依据后取消未完成事项，不能覆盖处理历史");String hash=requestHash("CANCEL",id,in);if(replay(p,id,in.requestId(),hash))return detail(id);version(row,in.expectedVersion());if(!Set.of("OPEN","IN_PROGRESS","REWORK").contains(row.get("status")))throw conflict("已提交独立核实或已结束的事项不能直接取消");change(p,row,"CANCELLED",in.requestId(),in.note(),hash,List.of(),false);notify(p,id,id(row.get("owner_id")),"CANCELLED",in.expectedVersion()+1);return detail(id);}
 private String requestHash(String action,UUID id,Object input){return FinanceService.hash(json(Map.of("action",action,"task",id,"input",input)));}
 private boolean replay(TenantPrincipal p,UUID task,UUID request,String hash){var rows=jdbc.queryForList("select task_id,request_hash,actor_id from fi_action_update where tenant_id=:tenant and id=:request",base(p).addValue("request",request));if(rows.isEmpty())return false;var row=rows.getFirst();if(!task.equals(row.get("task_id"))||!hash.equals(row.get("request_hash"))||!p.actorId().equals(row.get("actor_id")))throw conflict("办理请求编号已绑定其他事项、版本或操作人");return true;}
 private void change(TenantPrincipal p,Map<String,Object> row,String state,UUID request,String note,String hash,List<UUID> proofs,boolean submit){int next=((Number)row.get("version")).intValue()+1;var b=base(p).addValue("id",row.get("id")).addValue("state",state).addValue("next",next).addValue("submission",submit?next:row.get("submission_version")).addValue("submitted",submit?p.actorId():row.get("submitted_by")).addValue("reviewed",state.equals("DONE")?p.actorId():null);jdbc.update("update fi_action_task set status=:state,version=:next,submission_version=:submission,submitted_by=:submitted,reviewed_by=:reviewed,reviewed_at=case when :state='DONE' then now() else null end,updated_at=now() where tenant_id=:tenant and id=:id",b);record(p,id(row.get("id")),request,row.get("status").toString(),state,next,note,hash,proofs);audit.record("FINANCE_INSIGHT_ACTION_"+state,"FI_ACTION",id(row.get("id")),json(Map.of("version",next,"requestId",request,"evidence",proofs,"noExecutionActions",true)));}
 private void record(TenantPrincipal p,UUID task,UUID request,String from,String to,int version,String note,String hash,List<UUID> proofs){if(note==null||note.isBlank()||note.length()>4000)throw bad("必须填写不超过4000字的真实办理或独立核实依据");jdbc.update("insert into fi_action_update(id,tenant_id,task_id,from_status,to_status,task_version,note,actor_id,request_hash,evidence_ids) values(:request,:tenant,:id,:from,:to,:version,:note,:actor,:hash,cast(:proofs as uuid[]))",base(p).addValue("request",request).addValue("id",task).addValue("from",from).addValue("to",to).addValue("version",version).addValue("note",note).addValue("hash",hash).addValue("proofs","{"+String.join(",",proofs.stream().map(UUID::toString).toList())+"}"));}
 private void notify(TenantPrincipal p,UUID task,UUID recipient,String event,int version){jdbc.update("insert into notification(tenant_id,recipient_account_id,notification_type,title,content,source_type,source_id,idempotency_key) values(:tenant,:recipient,'FINANCE_INSIGHT_ACTION_PENDING','财务分析建议跟进状态更新','您有一项明确分配的财务建议跟进或独立核实事项。请进入岗位工作台查看当前节点；本消息不包含敏感明细，也不代表财务执行已完成。','FINANCE_INSIGHT_ACTION',:id,:key) on conflict(tenant_id,recipient_account_id,idempotency_key) do nothing",base(p).addValue("recipient",recipient).addValue("id",task).addValue("key","fi-action:"+task+":"+event+":"+version));}
}
